using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;
namespace IdleRestaurant.Editor {public static class RestaurantFamilySetup {
[MenuItem("Restaurant/Family Game/Configure free family edition")]
public static void Configure(){var app=Object.FindAnyObjectByType<RestaurantApp>();var catalog=app.catalog;const string path="Assets/Restaurant/Production/Data/FamilyBalance.asset";var balance=AssetDatabase.LoadAssetAtPath<FamilyBalance>(path);if(!balance){balance=ScriptableObject.CreateInstance<FamilyBalance>();AssetDatabase.CreateAsset(balance,path);}catalog.familyBalance=balance;balance.rankIncomeGrowth=1.1;PlayerSettings.runInBackground=false;catalog.maxRank=0;foreach(var node in catalog.research){node.income=0;if(node.key=="ccr")node.title="Thoughtful service";if(node.key=="cbus")node.title="Comfort diner skills";if(node.key=="ctrn")node.title="Asian kitchen skills";if(node.key=="cshp")node.title="Bistro skills";if(node.key=="ctrk")node.title="Dessert cafe skills";node.effect=node.key=="tds"||node.key=="bds"||node.key=="cds"?.0045:.01;}app.gameCamera.rect=new Rect(0,.32f,1,.4f);PlayerSettings.bundleVersion="0.3.0";PlayerSettings.Android.bundleVersionCode=3;EditorUtility.SetDirty(catalog);EditorUtility.SetDirty(balance);EditorSceneManager.MarkSceneDirty(app.gameObject.scene);AssetDatabase.SaveAssets();EditorSceneManager.SaveOpenScenes();Debug.Log("Free family edition configured");}
}}
